-- 2026-11-19: the podcast spotlight reel template, LOCKED by Sean ("Lock it"). Canon canon-ve-brand-kit-templates v3 and the playbook. Safe to run twice.
update public.knowledge_records set version = 3, updated_by = 'logan', updated_at = now(),
  change_summary = 'v3 (Sean, 2026-11-19, "Lock it"): the podcast spotlight reel joins the templates.',
  body = jsonb_set(body, '{podcast_spotlight_reel}', $j$"LOCKED by Sean 2026-11-19 (\"a reel using our branding where we can fit in those clips in the horizontal format... incorporate elements of their city\"; then \"make sure we're in the safe margins, because on Facebook and in reposts, it tends to blow it up\"; then \"Lock it\"). 9:16, 1080x1920, renderer scripts/brand-templates/podcast-spotlight-reel.js (--guides draws the safe zones). Top: the section-color band (Directory brand green for a restaurant) with an ink-on-white label (\"Vegan Directory · <city>\"), the white suitcase mark left of a two-row hook, the stripe under it; band and logo stay still the whole reel. Middle: the interview clip horizontal (16:9) in a white page, framed with an ink border and hard shadow; under it the name bar: the business logo as a rounded square exactly as tall as the words, \"<Name> · <Business>\" and \"<City> · Vegans Explore Podcast, Ep N\". Bottom: the city's own 16:9 art, whole, never cropped; captions (their real words, Vegan capitalized) on a white plate with an ink shadow over the sky. End card: same band with \"More Vegan spots / in <City>\" or \"More places like / <Business>\", one line pointing to the Vegans Explore Directory, the orange vegansexplore.com button, the landscape logo. SAFE BOX: every word, the clip and the name bar inside x 90 to 960, y 300 to 1620 (inside Facebook's 4:5 feed crop y 285 to 1635, clear of Instagram's top 250 px, bottom 340 px and the right 120 px of buttons); only color and city art reach the edges. First two: An of Sen Saigon (Ep 62, New York) and Veronica Menon of Love Life Cafe (Ep 56, Miami)."$j$::jsonb)
where slug = 'canon-ve-brand-kit-templates' and status = 'active' and version = 2;

insert into playbook_records (slug, brand_slug, author, body, source, kind, created_at)
select 've-social-schedule', 'vegans-explore', 'Logan', $b$Podcast spotlight reel LOCKED by Sean 2026-11-19 ("Lock it"), after the safe-margin pass and the An (not Ann) fix. Canon canon-ve-brand-kit-templates v3 (podcast_spotlight_reel), renderer scripts/brand-templates/podcast-spotlight-reel.js, CLAUDE.md template table. WAITING ON SEAN: the two episode videos (Ep 62 Sen Saigon, Ep 56 Love Life Cafe) dropped in Drive Ideas 111926 (YouTube is blocked from the build session). Then Logan cuts both reels, shows them, and drafts the 2-day notes to An and Veronica for Sean's approval.$b$, 'text', 'decision', now()
where not exists (select 1 from playbook_records where slug = 've-social-schedule' and body like 'Podcast spotlight reel LOCKED by Sean 2026-11-19%');
